    {
        int timer = 0;
        if (!hasObjVar(self, "timer"))
        {
            timer = 25;
        }
        else 
        {
            timer = getIntObjVar(self, "timer");
            if (timer < 0)
            {
                timer = 25;
            }
        }
        messageTo(self, "selfDestruct", null, timer, false);
        return SCRIPT_CONTINUE;
    }
